class Solution
{
public:
    int depthSumInverse(vector<NestedInteger>& nestedList)
    {
        queue<NestedInteger> q;
        for (const auto& item : nestedList) q.push(item);
        int running = 0, answer = 0;
        while (!q.empty())
        {
            int count = q.size();
            while (count--)
            {
                NestedInteger item = q.front();
                q.pop();
                if (item.isInteger())
                {
                    running += item.getInteger();
                } else
                {
                    for (const auto& child : item.getList()) q.push(child);
                }
            }
            answer += running;
        }
        return answer;
    }
};
